import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  MenuItem,
  Paper,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import SaveIcon from '@mui/icons-material/Save';
import api from '../../services/api';
import { hasPermission } from '../common/permissions';

const emptyForm = {
  loss_date: new Date().toISOString().slice(0, 10),
  event_title: '',
  description: '',
  department_id: '',
  risk_id: '',
  she_event_id: '',
  financial_impact: 0,
  non_financial_impact: '',
  root_cause: '',
  status: 'Open',
  evidence: ''
};

const LossEvents = ({ user }) => {
  const [events, setEvents] = useState([]);
  const [metadata, setMetadata] = useState({ risks: [], sheEvents: [], departments: [] });
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [search, setSearch] = useState('');
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const [notice, setNotice] = useState({ open: false, message: '', severity: 'success' });

  const canAdd = hasPermission(user, 'Loss Events', 'add');
  const canEdit = hasPermission(user, 'Loss Events', 'edit');
  const canDelete = hasPermission(user, 'Loss Events', 'delete');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [eventsRes, metaRes] = await Promise.all([
        api.get('/loss-events'),
        api.get('/loss-metadata')
      ]);
      setEvents(eventsRes.data || []);
      setMetadata(metaRes.data || { risks: [], sheEvents: [], departments: [] });
    } catch (error) {
      setNotice({ open: true, message: error.response?.data?.message || 'Unable to load loss events.', severity: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const departmentName = (id) => metadata.departments?.find(d => d.id === id)?.name || id || 'Unassigned';

  const filtered = useMemo(() => {
    const term = search.toLowerCase();
    return events.filter(event =>
      event.loss_reference?.toLowerCase().includes(term) ||
      event.event_title?.toLowerCase().includes(term) ||
      event.root_cause?.toLowerCase().includes(term) ||
      departmentName(event.department_id)?.toLowerCase().includes(term)
    );
  }, [events, search, metadata.departments]);

  const totals = useMemo(() => {
    const total = events.reduce((sum, item) => sum + Number(item.financial_impact || 0), 0);
    const open = events.filter(item => !['Closed', 'Resolved'].includes(item.status)).length;
    const linked = events.filter(item => item.risk_id || item.she_event_id).length;
    return { total, open, linked };
  }, [events]);

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm);
    setDialogOpen(true);
  };

  const openEdit = (event) => {
    setEditing(event);
    setForm({
      loss_date: event.loss_date ? event.loss_date.slice(0, 10) : emptyForm.loss_date,
      event_title: event.event_title || '',
      description: event.description || '',
      department_id: event.department_id || '',
      risk_id: event.risk_id || '',
      she_event_id: event.she_event_id || '',
      financial_impact: event.financial_impact || 0,
      non_financial_impact: event.non_financial_impact || '',
      root_cause: event.root_cause || '',
      status: event.status || 'Open',
      evidence: event.evidence || ''
    });
    setDialogOpen(true);
  };

  const save = async () => {
    if (saving) return;

    if (Number(form.financial_impact || 0) < 0) {
      setNotice({ open: true, message: 'Actual Financial Loss cannot be negative.', severity: 'error' });
      return;
    }

    setSaving(true);
    try {
      const payload = {
        ...form,
        risk_id: form.risk_id || null,
        she_event_id: form.she_event_id || null,
        department_id: form.department_id || null,
        financial_impact: Number(form.financial_impact || 0)
      };
      const response = editing
        ? await api.put(`/loss-events/${editing.loss_id}`, payload)
        : await api.post('/loss-events', payload);
      const savedEvent = response.data?.event;
      if (savedEvent) {
        setEvents(current => editing
          ? current.map(item => item.loss_id === savedEvent.loss_id ? savedEvent : item)
          : [savedEvent, ...current]
        );
      }
      setNotice({ open: true, message: editing ? 'Loss event updated.' : 'Loss event recorded.', severity: 'success' });
      setDialogOpen(false);
    } catch (error) {
      setNotice({ open: true, message: error.response?.data?.message || 'Unable to save loss event.', severity: 'error' });
    } finally {
      setSaving(false);
    }
  };

  const remove = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await api.delete(`/loss-events/${deleteTarget.loss_id}`);
      setEvents(current => current.filter(item => item.loss_id !== deleteTarget.loss_id));
      setNotice({ open: true, message: 'Loss event deleted.', severity: 'success' });
      setDeleteTarget(null);
    } catch (error) {
      setNotice({ open: true, message: error.response?.data?.message || 'Unable to delete loss event.', severity: 'error' });
    } finally {
      setDeleting(false);
    }
  };

  const money = (value) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(Number(value || 0));

  const fieldSx = {
    '& .MuiInputBase-root': {
      color: '#f8fafc',
      background: 'rgba(15, 23, 42, 0.45)'
    },
    '& .MuiInputLabel-root': {
      color: '#cbd5e1'
    },
    '& .MuiInputLabel-root.Mui-focused': {
      color: '#f8fafc'
    },
    '& .MuiOutlinedInput-notchedOutline': {
      borderColor: 'rgba(203, 213, 225, 0.28)'
    },
    '& .MuiOutlinedInput-root:hover .MuiOutlinedInput-notchedOutline': {
      borderColor: 'rgba(248, 250, 252, 0.45)'
    },
    '& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline': {
      borderColor: '#10b981'
    },
    '& .MuiSelect-icon, & input[type="date"]::-webkit-calendar-picker-indicator': {
      filter: 'invert(1)',
      color: '#f8fafc'
    }
  };

  const selectMenuProps = {
    MenuProps: {
      PaperProps: {
        sx: {
          bgcolor: '#1e293b',
          color: '#f8fafc',
          border: '1px solid rgba(255,255,255,0.12)'
        }
      }
    }
  };

  if (loading) {
    return <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}><CircularProgress sx={{ color: '#10b981' }} /></Box>;
  }

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, alignItems: 'center', mb: 3, flexWrap: 'wrap' }}>
        <Typography variant="h4" className="gradient-text" sx={{ fontWeight: 'bold' }}>Loss Events</Typography>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <TextField size="small" placeholder="Search losses..." value={search} onChange={(e) => setSearch(e.target.value)} sx={{ minWidth: 260, '& .MuiOutlinedInput-root': { color: 'white', background: 'rgba(255,255,255,0.04)' } }} />
          {canAdd && <Button variant="contained" onClick={openCreate} sx={{ textTransform: 'none', fontWeight: 'bold', bgcolor: '#10b981' }}>Record Loss</Button>}
        </Box>
      </Box>

      <Grid container spacing={2} sx={{ mb: 3 }}>
        {[
          ['Total Actual Loss', money(totals.total), '#ef4444'],
          ['Open Loss Events', totals.open, '#f59e0b'],
          ['Linked to Risk/SHE', totals.linked, '#3b82f6']
        ].map(([label, value, color]) => (
          <Grid item xs={12} md={4} key={label}>
            <Paper className="glass" sx={{ p: 2.5, borderRadius: '16px', background: 'rgba(30,41,59,0.45)' }}>
              <Typography sx={{ color: '#94a3b8', fontSize: '0.8rem' }}>{label}</Typography>
              <Typography sx={{ color, fontSize: '1.5rem', fontWeight: 'bold' }}>{value}</Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <TableContainer component={Paper} sx={{ background: 'rgba(15,23,42,0.75)', borderRadius: '18px', border: '1px solid rgba(255,255,255,0.08)' }}>
        <Table>
          <TableHead>
            <TableRow sx={{ '& th': { color: '#94a3b8', fontWeight: 'bold' } }}>
              <TableCell>Reference</TableCell>
              <TableCell>Date</TableCell>
              <TableCell>Event</TableCell>
              <TableCell>Department</TableCell>
              <TableCell>Actual Financial Loss</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Linked Records</TableCell>
              <TableCell align="right">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {filtered.map(event => (
              <TableRow key={event.loss_id} sx={{ '& td': { color: '#f1f5f9', borderColor: 'rgba(255,255,255,0.05)' } }}>
                <TableCell sx={{ color: '#10b981 !important', fontWeight: 'bold' }}>{event.loss_reference}</TableCell>
                <TableCell>{event.loss_date?.slice(0, 10)}</TableCell>
                <TableCell>
                  <Typography sx={{ fontWeight: 'bold', fontSize: '0.9rem' }}>{event.event_title}</Typography>
                  <Typography sx={{ color: '#94a3b8', fontSize: '0.75rem' }}>{event.root_cause || 'Root cause not captured'}</Typography>
                </TableCell>
                <TableCell>{departmentName(event.department_id)}</TableCell>
                <TableCell>{money(event.financial_impact)}</TableCell>
                <TableCell><Chip size="small" label={event.status} sx={{ color: event.status === 'Closed' ? '#10b981' : '#f59e0b', bgcolor: 'rgba(255,255,255,0.05)', fontWeight: 'bold' }} /></TableCell>
                <TableCell sx={{ color: '#94a3b8 !important' }}>{event.risk?.sn || event.she_event?.action_id || 'None'}</TableCell>
                <TableCell align="right">
                  <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, flexWrap: 'wrap' }}>
                    {canEdit && (
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={() => openEdit(event)}
                        sx={{
                          color: '#3b82f6',
                          borderColor: 'rgba(59, 130, 246, 0.55)',
                          textTransform: 'none',
                          fontWeight: 'bold',
                          borderRadius: '8px',
                          minWidth: 72,
                          '&:hover': { borderColor: '#3b82f6', background: 'rgba(59, 130, 246, 0.1)' }
                        }}
                      >
                        Edit
                      </Button>
                    )}
                    {canDelete && (
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={() => setDeleteTarget(event)}
                        sx={{
                          color: '#ef4444',
                          borderColor: 'rgba(239, 68, 68, 0.55)',
                          textTransform: 'none',
                          fontWeight: 'bold',
                          borderRadius: '8px',
                          minWidth: 88,
                          '&:hover': { borderColor: '#ef4444', background: 'rgba(239, 68, 68, 0.1)' }
                        }}
                      >
                        Delete
                      </Button>
                    )}
                  </Box>
                </TableCell>
              </TableRow>
            ))}
            {filtered.length === 0 && (
              <TableRow><TableCell colSpan={8} align="center" sx={{ color: '#64748b', py: 6 }}>No loss events found.</TableCell></TableRow>
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="md" fullWidth PaperProps={{ sx: { background: '#1e293b', color: 'white', borderRadius: '18px' } }}>
        <DialogTitle sx={{ fontWeight: 'bold' }}>{editing ? `Edit ${editing.loss_reference}` : 'Record Loss Event'}</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 0.5 }}>
            <Grid item xs={12} md={6}><TextField fullWidth label="Event Title" value={form.event_title} onChange={(e) => setForm({ ...form, event_title: e.target.value })} sx={fieldSx} /></Grid>
            <Grid item xs={12} md={3}><TextField fullWidth type="date" label="Loss Date" InputLabelProps={{ shrink: true }} value={form.loss_date} onChange={(e) => setForm({ ...form, loss_date: e.target.value })} sx={fieldSx} /></Grid>
            <Grid item xs={12} md={3}><TextField fullWidth type="number" label="Actual Financial Loss" value={form.financial_impact} inputProps={{ min: 0 }} onChange={(e) => setForm({ ...form, financial_impact: e.target.value })} sx={fieldSx} /></Grid>
            <Grid item xs={12} md={4}><TextField select fullWidth label="Department" value={form.department_id} onChange={(e) => setForm({ ...form, department_id: e.target.value })} sx={fieldSx} SelectProps={selectMenuProps}>{metadata.departments?.map(d => <MenuItem key={d.id} value={d.id}>{d.name}</MenuItem>)}</TextField></Grid>
            <Grid item xs={12} md={4}>
              <TextField select fullWidth label="Linked Risk" value={form.risk_id} onChange={(e) => setForm({ ...form, risk_id: e.target.value })} sx={fieldSx} SelectProps={selectMenuProps}>
                <MenuItem value="">None</MenuItem>
                {metadata.risks?.map(r => (
                  <MenuItem key={r.id} value={r.id}>
                    {r.sn} - {r.risk_description?.length > 70 ? `${r.risk_description.slice(0, 70)}...` : r.risk_description}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField select fullWidth label="Linked SHE Event" value={form.she_event_id} onChange={(e) => setForm({ ...form, she_event_id: e.target.value })} sx={fieldSx} SelectProps={selectMenuProps}>
                <MenuItem value="">None</MenuItem>
                {metadata.sheEvents?.map(s => {
                  const sheDescription = s.description || s.activity_category || 'SHE record';
                  return (
                    <MenuItem key={s.id} value={s.id}>
                      {s.action_id} - {s.activity_category} - {sheDescription.length > 55 ? `${sheDescription.slice(0, 55)}...` : sheDescription}
                    </MenuItem>
                  );
                })}
              </TextField>
            </Grid>
            <Grid item xs={12} md={4}><TextField select fullWidth label="Status" value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} sx={fieldSx} SelectProps={selectMenuProps}>{['Open', 'Under Review', 'Resolved', 'Closed'].map(v => <MenuItem key={v} value={v}>{v}</MenuItem>)}</TextField></Grid>
            <Grid item xs={12} md={8}><TextField fullWidth label="Root Cause" value={form.root_cause} onChange={(e) => setForm({ ...form, root_cause: e.target.value })} sx={fieldSx} /></Grid>
            <Grid item xs={12}><TextField fullWidth multiline minRows={3} label="Description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} sx={fieldSx} /></Grid>
            <Grid item xs={12}><TextField fullWidth multiline minRows={2} label="Non-financial Impact" value={form.non_financial_impact} onChange={(e) => setForm({ ...form, non_financial_impact: e.target.value })} sx={fieldSx} /></Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ p: 3 }}>
          <Button onClick={() => setDialogOpen(false)} sx={{ color: '#94a3b8', textTransform: 'none' }}>Cancel</Button>
          <Button variant="contained" startIcon={<SaveIcon />} onClick={save} disabled={saving} sx={{ bgcolor: '#10b981', textTransform: 'none', fontWeight: 'bold', '&.Mui-disabled': { bgcolor: 'rgba(16,185,129,0.45)', color: '#d1fae5' } }}>{saving ? 'Saving...' : 'Save'}</Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={Boolean(deleteTarget)}
        onClose={() => !deleting && setDeleteTarget(null)}
        PaperProps={{
          sx: {
            background: '#1e293b',
            color: 'white',
            borderRadius: '16px',
            border: '1px solid rgba(255,255,255,0.1)',
            p: 1,
            minWidth: 360
          }
        }}
      >
        <DialogTitle sx={{ color: '#ef4444', fontWeight: 'bold' }}>Confirm Delete</DialogTitle>
        <DialogContent>
          <Typography sx={{ color: '#cbd5e1', mb: 2 }}>
            Delete this loss event record? This action cannot be undone.
          </Typography>
          {deleteTarget && (
            <Box sx={{ p: 2, borderRadius: '10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.08)' }}>
              <Typography sx={{ color: '#10b981', fontWeight: 'bold', fontSize: '0.9rem' }}>{deleteTarget.loss_reference}</Typography>
              <Typography sx={{ color: '#f8fafc', fontSize: '0.85rem', mt: 0.5 }}>{deleteTarget.event_title}</Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 3, pt: 1 }}>
          <Button onClick={() => setDeleteTarget(null)} disabled={deleting} sx={{ color: '#94a3b8', textTransform: 'none' }}>Cancel</Button>
          <Button
            variant="contained"
            onClick={remove}
            disabled={deleting}
            sx={{ bgcolor: '#ef4444', textTransform: 'none', fontWeight: 'bold', '&:hover': { bgcolor: '#dc2626' } }}
          >
            {deleting ? 'Deleting...' : 'Delete Record'}
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar open={notice.open} autoHideDuration={4000} onClose={() => setNotice({ ...notice, open: false })}>
        <Alert severity={notice.severity} variant="filled">{notice.message}</Alert>
      </Snackbar>
    </Box>
  );
};

export default LossEvents;
